# Physics, electricity, magnetism and modern physics (10+2 CBSE):
# electrostatics, current electricity, magnetic effects, electromagnetic
# induction and AC, electromagnetic waves, dual nature, atoms and nuclei,
# semiconductors.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Electrostatics", "The distance between two point charges is made three times as large. The electrostatic force between them becomes",
      ["one-ninth", "one-third", "three times", "nine times"],
      r"Coulomb's law: $F \propto 1/r^2$. Tripling r divides the force by $3^2 = 9$. One-third forgets to square the distance."),
    S(1, 1, "Current electricity", "Three resistors of 6 Ω each are connected in parallel. What is their equivalent resistance?",
      ["2 Ω", "18 Ω", "3 Ω", "6 Ω"],
      "1/R = 1/6 + 1/6 + 1/6 = 3/6, so R = 2 Ω. 18 Ω is the series value. A parallel combination is always smaller than the smallest resistor."),
    S(1, 2, "Current electricity", "A 24 V battery is connected across an 8 Ω resistor. How much power is dissipated in the resistor?",
      ["72 W", "9 W", "3 W", "24 W"],
      "Current I = V / R = 24 / 8 = 3 A. Power P = VI = 24 x 3 = 72 W (or V²/R = 576 / 8). 9 W squares the current but leaves out R, 3 is the current in amperes, and 24 W takes the voltage as the power."),
    S(1, 2, "Capacitors", "Capacitors of 2 µF and 3 µF are connected in series. What is their equivalent capacitance?",
      ["1.2 µF", "5 µF", "6 µF", "2.5 µF"],
      "In series, 1/C = 1/2 + 1/3 = 5/6, so C = 6/5 = 1.2 µF. 5 µF is the parallel value. Capacitors in series combine like resistors in parallel."),
    S(1, 2, "Magnetic effects of current", "A charged particle moves parallel to a uniform magnetic field. What magnetic force acts on it?",
      ["Zero", "Maximum, along the field", "Maximum, at right angles to the field", "Equal to qvB along its motion"],
      "The magnetic force is F = qvB sin θ. For motion parallel to the field, θ = 0 and sin 0 = 0, so there is no force and the particle keeps moving in a straight line."),
    S(1, 2, "Electromagnetic induction", "Lenz's law, which gives the direction of an induced current, is a consequence of the conservation of",
      ["energy", "charge", "momentum", "mass"],
      "The induced current always opposes the change that produces it, so work must be done to keep the change going. If it helped the change, energy would be created from nothing."),
    S(1, 1, "Alternating current", "An ideal step-up transformer has 100 turns on its primary and 500 turns on its secondary. If the input is 220 V AC, what is the output voltage?",
      ["1100 V", "44 V", "220 V", "550 V"],
      "Vs / Vp = Ns / Np, so Vs = 220 x 500 / 100 = 1100 V. 44 V inverts the turns ratio, which would be a step-down transformer."),
    S(1, 2, "Dual nature of radiation", "In the photoelectric effect, increasing the intensity of light (above the threshold frequency) increases",
      ["the number of photoelectrons emitted per second", "the maximum kinetic energy of the photoelectrons", "the threshold frequency of the metal", "the work function of the metal"],
      "Brighter light means more photons each second, so more electrons are emitted. The maximum kinetic energy depends on the frequency, not the intensity, and the threshold frequency and work function belong to the metal."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Electrostatics", "What is the electric field inside a charged, hollow conducting sphere?",
      ["Zero", "Maximum at the centre", "Equal to the field at the surface", "Directed towards the surface"],
      "Charge on a conductor sits on its outer surface, and the field inside is zero. This is why a metal cage or an aircraft's body shields the people inside from a lightning strike."),
    S(2, 2, "Current electricity", "Kirchhoff's junction rule (the current law) is based on the conservation of",
      ["charge", "energy", "momentum", "mass"],
      "The current entering a junction equals the current leaving it, because charge cannot pile up or vanish at the junction. The loop rule is based on conservation of energy."),
    S(2, 2, "Current electricity", "A wire is stretched uniformly to twice its original length. Its resistance becomes",
      ["four times", "twice", "half", "the same"],
      "Stretching keeps the volume the same, so doubling the length halves the cross-sectional area. R = ρL/A, so R becomes 2 / (1/2) = 4 times."),
    S(2, 2, "Current electricity", "What is the resistance of the filament of a bulb rated 100 W, 220 V when it is working normally?",
      ["484 Ω", "2.2 Ω", "0.45 Ω", "242 Ω"],
      "P = V²/R, so R = V²/P = 220² / 100 = 48400 / 100 = 484 Ω. 2.2 Ω is V/P, 242 Ω is half the right value (dividing by 2P) and 0.45 is P/V, which is the current in amperes."),
    S(2, 1, "Magnetic effects of current", "A galvanometer is converted into an ammeter by connecting",
      ["a low resistance in parallel with it", "a high resistance in series with it", "a low resistance in series with it", "a high resistance in parallel with it"],
      "A small shunt resistance in parallel carries most of the current, so the meter can measure large currents and has a low total resistance. A high resistance in series turns it into a voltmeter."),
    S(2, 2, "Alternating current", "The mains supply is 220 V rms. What is its peak voltage, approximately?",
      ["311 V", "220 V", "156 V", "440 V"],
      r"Peak voltage $V_0 = \sqrt{2} \times V_{rms} = 1.414 \times 220 \approx 311$ V. 156 V divides by $\sqrt{2}$ instead of multiplying."),
    S(2, 2, "Atoms", "The energy of the electron in the ground state of a hydrogen atom is -13.6 eV. How much energy is needed to ionise the atom from this state?",
      ["13.6 eV", "3.4 eV", "10.2 eV", "1.51 eV"],
      "Ionisation lifts the electron from -13.6 eV to 0 eV, so it needs 13.6 eV. 10.2 eV only lifts it to the first excited state (-3.4 eV)."),
    S(2, 1, "Semiconductors", "A p-type semiconductor is made by adding to pure silicon a small amount of",
      ["a trivalent element such as boron", "a pentavalent element such as phosphorus", "a noble gas such as neon", "a metal such as copper"],
      "A trivalent atom has one electron too few to complete the bonds, leaving a hole. Holes are the majority carriers in p-type material. A pentavalent dopant gives n-type."),

    # ---------- Drill only ----------
    S(0, 2, "Electrostatics", "About how many electrons make up a charge of 1 coulomb?",
      [r"$6.25 \times 10^{18}$", r"$1.6 \times 10^{19}$", r"$1.6 \times 10^{-19}$", r"$6.02 \times 10^{23}$"],
      r"One electron carries $1.6 \times 10^{-19}$ C, so 1 C needs $1 / (1.6 \times 10^{-19}) = 6.25 \times 10^{18}$ electrons. $6.02 \times 10^{23}$ is Avogadro's number."),
    S(0, 1, "Electrostatics", "How much work is done in moving a charge of 2 C through a potential difference of 5 V?",
      ["10 J", "2.5 J", "0.4 J", "7 J"],
      "W = qV = 2 x 5 = 10 J. 2.5 J divides V by q, 0.4 J divides q by V, and 7 J adds them."),
    S(0, 1, "Electromagnetic waves", "Which of these electromagnetic radiations has the highest frequency?",
      ["Gamma rays", "X-rays", "Ultraviolet rays", "Microwaves"],
      "In order of rising frequency: radio waves, microwaves, infrared, visible light, ultraviolet, X-rays, gamma rays. Gamma rays have the highest frequency and shortest wavelength."),
    S(0, 2, "Nuclei", "A radioactive sample has a half-life of 10 days. What fraction of it is left undecayed after 30 days?",
      ["1/8", "1/3", "1/6", "1/4"],
      "30 days is three half-lives, so the fraction left is (1/2)³ = 1/8. 1/3 wrongly divides 10 by 30."),
    S(0, 1, "Semiconductors", "Which logic gate gives an output of 1 only when both of its inputs are 1?",
      ["AND", "OR", "NAND", "XOR"],
      "AND gives 1 only for inputs 1 and 1. OR gives 1 if either input is 1, NAND is the opposite of AND, and XOR gives 1 only when the inputs differ."),
    S(0, 2, "Magnetism and matter", "Which kind of material is weakly repelled by a magnet?",
      ["Diamagnetic", "Paramagnetic", "Ferromagnetic", "Ferrimagnetic"],
      "Diamagnetic materials such as bismuth, copper and water are weakly repelled. Paramagnetic materials are weakly attracted and ferromagnetic ones such as iron strongly attracted."),
    S(0, 1, "Electromagnetic induction", "What is the SI unit of self-inductance?",
      ["Henry", "Tesla", "Weber", "Farad"],
      "Self-inductance is measured in henry (H). The tesla is the unit of magnetic field, the weber of magnetic flux, and the farad of capacitance."),
    S(0, 2, "Dual nature of radiation", "If the momentum of a particle is doubled, its de Broglie wavelength becomes",
      ["half", "double", "four times", "one-fourth"],
      r"$\lambda = h / p$, so the wavelength is inversely proportional to momentum. Doubling p halves λ."),
]
